#!/bin/bash

function storePassword {
    local userName=$1
    local Password=$2
    local hashedPassword
    hashedPassword=$(echo -n "$Password" | sha384sum | awk '{print $1}')
    echo "Updating login for $userName with password $hashedPassword"
    return 0
}

storePassword "insufficientSaltUser" "insufficientSaltPwd"

#!/bin/bash

function processData {
    local data=$1
    printf '%.0s' {1..10000} | tr -d '\n' | xargs -I {} echo -n "$data"
}

function sendDataToServer {
    local data=$1
    echo -n "$data" >/dev/udp/127.0.0.1/5388
}

function handleRequest {
    local user_input=$1
    if [[ -n $user_input ]]; then
        echo "Processing data..."
        local result=$(processData "$user_input")
        echo "Data processed successfully."
        echo "Sending 10000*$user_input."
        sendDataToServer "$result"
    else
        echo "No input provided."
    fi
}

user_input="a"
handleRequest "$user_input"

#!/bin/bash

function processData {
    local data=$1
    echo $(($data * 10000))
}

function sendDataToServer {
    local data=$1
    echo "$data" | nc -u 127.0.0.1 5388
}

function handleRequest {
    local user_input=$1
    if [[ -n $user_input ]]; then
        echo "Processing data..."
        local result=$(processData $user_input)
        echo "Data processed successfully."
        echo "Sending 10000*$user_input."
        sendDataToServer $result
    else
        echo "No input provided."
    fi
}

user_input="a"
handleRequest $user_input

#!/bin/bash

function process_command {
    case $1 in
        "start")
            echo "Starting the system."
            ;;
        "stop")
            echo "Stopping the system."
            ;;
        "restart")
            echo "Restarting the system."
            ;;
        *)
            return 1
            ;;
    esac
}

process_command "pause"
if [ $? -eq 1 ]; then
    echo "No default case for the command."
fi

#!/bin/bash
function calculate_discount {
    local item=$1
    case $item in
        "book")
            echo 0.1
            ;;
        "game")
            echo 0.2
            ;;
        "food")
            echo 0.05
            ;;
        *)
            echo "none"
            ;;
    esac
}

discount=$(calculate_discount "clothes")
if [ "$discount" == "none" ]; then
    echo "No default case for calculating the discount."
fi

